export const adminApi = {
  definirAtivo: (usuarioId, ativo) => request(`/admin/usuarios/${usuarioId}/ativo`, { metodo: 'PATCH', corpo: { ativo } }),
  resumo: (dataInicio, dataFim) => request('/admin/relatorios/resumo', { params: { dataInicio, dataFim } }),
